// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Get global memory statistics.
	// (GET /api/stats/memory)
	GetMemoryStats(w http.ResponseWriter, r *http.Request)
	// Get torrent statistics.
	// (GET /api/stats/torrents/{hash})
	GetTorrentStats(w http.ResponseWriter, r *http.Request, hash Hash)
	// Health check.
	// (GET /api/system/health)
	HealthCheck(w http.ResponseWriter, r *http.Request)
	// Get application information.
	// (GET /api/system/info)
	GetSystemInfo(w http.ResponseWriter, r *http.Request)
	// Get recent application logs.
	// (GET /api/system/logs)
	GetLogs(w http.ResponseWriter, r *http.Request, params GetLogsParams)
	// Get system metrics.
	// (GET /api/system/metrics)
	GetSystemMetrics(w http.ResponseWriter, r *http.Request)
	// Generate a playlist for streaming.
	// (GET /api/v1/playlist)
	GetPlaylist(w http.ResponseWriter, r *http.Request, params GetPlaylistParams)
	// Get application settings.
	// (GET /api/v1/settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// Update application settings.
	// (PATCH /api/v1/settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// Stream a torrent file.
	// (GET /api/v1/stream/{hash})
	GetStream(w http.ResponseWriter, r *http.Request, hash Hash, params GetStreamParams)
	// Serve a HEAD request for a streamable torrent file.
	// (HEAD /api/v1/stream/{hash})
	HeadStream(w http.ResponseWriter, r *http.Request, hash Hash, params HeadStreamParams)
	// Create a scoped access token.
	// (POST /api/v1/tokens)
	CreateToken(w http.ResponseWriter, r *http.Request)
	// Resolve a torrent from a URL without storing it.
	// (POST /api/v1/torrent-resolutions)
	ResolveTorrent(w http.ResponseWriter, r *http.Request)
	// List all torrents.
	// (GET /api/v1/torrents)
	ListTorrents(w http.ResponseWriter, r *http.Request, params ListTorrentsParams)
	// Add a new torrent.
	// (POST /api/v1/torrents)
	AddTorrent(w http.ResponseWriter, r *http.Request)
	// Backup torrents and posters.
	// (GET /api/v1/torrents/backup)
	BackupTorrents(w http.ResponseWriter, r *http.Request)
	// Restore torrents and posters.
	// (POST /api/v1/torrents/restore)
	RestoreTorrents(w http.ResponseWriter, r *http.Request)
	// Delete a torrent.
	// (DELETE /api/v1/torrents/{hash})
	DeleteTorrent(w http.ResponseWriter, r *http.Request, hash Hash)
	// Get torrent metadata.
	// (GET /api/v1/torrents/{hash})
	GetTorrent(w http.ResponseWriter, r *http.Request, hash Hash, params GetTorrentParams)
	// Update torrent metadata.
	// (PATCH /api/v1/torrents/{hash})
	UpdateTorrent(w http.ResponseWriter, r *http.Request, hash Hash)
	// Cancel torrent preload.
	// (DELETE /api/v1/torrents/{hash}/preload)
	DeleteTorrentPreload(w http.ResponseWriter, r *http.Request, hash Hash)
	// Get torrent preload status.
	// (GET /api/v1/torrents/{hash}/preload)
	GetTorrentPreload(w http.ResponseWriter, r *http.Request, hash Hash)
	// Start or update torrent preloading.
	// (PUT /api/v1/torrents/{hash}/preload)
	PutTorrentPreload(w http.ResponseWriter, r *http.Request, hash Hash)
	// Add a new torrent (qBittorrent compatible).
	// (POST /api/v2/torrents/add)
	QBittorrentAddTorrent(w http.ResponseWriter, r *http.Request)
	// Get cache statistics (TorrServer compatible).
	// (POST /cache)
	TSCache(w http.ResponseWriter, r *http.Request)
	// Server status check (TorrServer compatible).
	// (GET /echo)
	TSEcho(w http.ResponseWriter, r *http.Request)
	// Get Prometheus metrics.
	// (GET /metrics)
	GetMetrics(w http.ResponseWriter, r *http.Request)
	// Obtain a JWT token.
	// (POST /oauth/token)
	GetToken(w http.ResponseWriter, r *http.Request)
	// Stream torrent content (TorrServer compatible).
	// (GET /play/{hash}/{index})
	TSPlay(w http.ResponseWriter, r *http.Request, hash Hash, index TSIndex, params TSPlayParams)
	// Update settings (TorrServer compatible).
	// (POST /settings)
	TSSettings(w http.ResponseWriter, r *http.Request)
	// Stream or preload torrent (TorrServer compatible).
	// (GET /stream/{filename})
	TSStream(w http.ResponseWriter, r *http.Request, filename TSFileName, params TSStreamParams)
	// Add a new torrent (TorrServer compatible).
	// (POST /torrent/upload)
	TSTorrentUpload(w http.ResponseWriter, r *http.Request)
	// Manage torrents (TorrServer compatible).
	// (POST /torrents)
	TSTorrents(w http.ResponseWriter, r *http.Request)
	// Manage torrent view tags (TorrServer compatible).
	// (POST /viewed)
	TSViewed(w http.ResponseWriter, r *http.Request)
}

